// Configure your price alerts
// Types: 'above', 'below', 'percent_change'
const alerts = [
  { symbol: 'AAPL', type: 'above', value: 200, message: 'Apple above $200' },
  { symbol: 'AAPL', type: 'below', value: 170, message: 'Apple below $170 - potential buy zone' },
  { symbol: 'NVDA', type: 'percent_change', value: 5, message: 'NVIDIA moved 5%+' },
  { symbol: 'SPY', type: 'percent_change', value: 2, message: 'S&P 500 moved 2%+' },
  { symbol: 'VIX', type: 'above', value: 25, message: 'VIX spike - fear in market' },
];

return alerts.map(a => ({ json: a }));

const alert = $('Get Alert Config').first().json;
const quote = $input.first().json;

const currentPrice = quote.c;
const previousClose = quote.pc;
const percentChange = ((currentPrice - previousClose) / previousClose * 100).toFixed(2);

let triggered = false;
let alertMessage = '';

switch (alert.type) {
  case 'above':
    triggered = currentPrice > alert.value;
    alertMessage = `📈 *${alert.symbol}* is now $${currentPrice} (above $${alert.value})`;
    break;
  case 'below':
    triggered = currentPrice < alert.value;
    alertMessage = `📉 *${alert.symbol}* is now $${currentPrice} (below $${alert.value})`;
    break;
  case 'percent_change':
    triggered = Math.abs(percentChange) > alert.value;
    const direction = percentChange > 0 ? '🟢' : '🔴';
    alertMessage = `${direction} *${alert.symbol}* moved ${percentChange}% (threshold: ${alert.value}%)`;
    break;
}

if (triggered) {
  return [{
    json: {
      symbol: alert.symbol,
      currentPrice,
      percentChange,
      message: alertMessage,
      customMessage: alert.message,
      triggered: true
    }
  }];
}

return [];
